/** The medico-legal case register — GET /api/v1/mlc/cases (who may call: holders of mlc.case.manage or mlc.register.view). */
export function listCasesMlc(query?: { status?: "Open" | "Closed" | null; date_from?: string | null; date_to?: string | null; case_type_id?: number | null; police_station_id?: number | null; patient_id?: number | null; overdue?: boolean | null; limit?: number }): Promise<MlcCaseListOut[]> {
  return api<MlcCaseListOut[]>("GET", withQuery(`/mlc/cases`, query), undefined);
}

/** A medico-legal case — GET /api/v1/mlc/cases/{mlc_id} (who may call: holders of mlc.case.manage or mlc.register.view). */
export function getCase(mlc_id: number): Promise<MlcCaseOut> {
  return api<MlcCaseOut>("GET", `/mlc/cases/${mlc_id}`, undefined);
}

/** The intimation to the police station (A4) — GET /api/v1/mlc/cases/{mlc_id}/print-payload (who may call: holders of mlc.case.manage or mlc.register.view). */
export function printCase(mlc_id: number): Promise<PrintOut_MlcPrintFieldsOut_> {
  return api<PrintOut_MlcPrintFieldsOut_>("GET", `/mlc/cases/${mlc_id}/print-payload`, undefined);
}

/** Medico-legal case types — GET /api/v1/mlc/case-types (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function caseTypes(query?: { include_inactive?: boolean }): Promise<MlcCaseTypeOut[]> {
  return api<MlcCaseTypeOut[]>("GET", withQuery(`/mlc/case-types`, query), undefined);
}

/** Add a medico-legal case type — POST /api/v1/mlc/case-types (who may call: holders of mlc.setup.manage). */
export function addCaseType(body: CaseTypeIn): Promise<MlcCaseTypeOut> {
  return api<MlcCaseTypeOut>("POST", `/mlc/case-types`, body, { idempotent: true });
}

/** Rename, reorder or retire a medico-legal case type — PATCH /api/v1/mlc/case-types/{case_type_id} (who may call: holders of mlc.setup.manage). */
export function updateCaseType(case_type_id: number, body: CaseTypeUpdateIn): Promise<MlcCaseTypeOut> {
  return api<MlcCaseTypeOut>("PATCH", `/mlc/case-types/${case_type_id}`, body);
}

/** Police stations and MLR hospitals (contact list) — GET /api/v1/mlc/contacts (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function contacts(query?: { contact_type?: "PoliceStation" | "MlrHospital" | "ReferralHospital" | "HealthOffice" | "TraumaCentre" | "BloodBank" | "RescueService" | "FireBrigade" | "PoliceEmergency" | "Ambulance" | "SocialService" | null; include_inactive?: boolean }): Promise<MlcContactOut[]> {
  return api<MlcContactOut[]>("GET", withQuery(`/mlc/contacts`, query), undefined);
}

/** Add a contact: police station, MLR hospital, referral hospital, rescue, ambulance, ... — POST /api/v1/mlc/contacts (who may call: holders of mlc.setup.manage). */
export function addContact(body: ContactIn): Promise<MlcContactOut> {
  return api<MlcContactOut>("POST", `/mlc/contacts`, body, { idempotent: true });
}

/** Update or retire a contact — PATCH /api/v1/mlc/contacts/{contact_id} (who may call: holders of mlc.setup.manage). */
export function updateContact(contact_id: number, body: ContactUpdateIn): Promise<MlcContactOut> {
  return api<MlcContactOut>("PATCH", `/mlc/contacts/${contact_id}`, body);
}

/** The emergency and referral contact list to display (PDF) — GET /api/v1/mlc/contacts/pdf (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function contactsPdf(): Promise<unknown> {
  return api<unknown>("GET", `/mlc/contacts/pdf`, undefined);
}
